'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isString = require( '@stdlib/assert/is-string' );
var Title = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Title, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `orient` property', function test( t ) {
	var v;

	v = new Title();
	t.strictEqual( hasOwnProp( v, 'orient' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'orient' ), true, 'returns expected value' );
	t.strictEqual( isString( v.orient ), true, 'returns expected value' );

	t.end();
});

tape( 'the constructor throws an error if provided an invalid `orient` option', function test( t ) {
	var values;
	var i;

	values = [
		'beep',
		'boop',
		'BOTTOM',
		5,
		NaN,
		null,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var title = new Title({ // eslint-disable-line no-unused-vars
				'orient': value
			});
		};
	}
});

tape( 'the constructor returns an instance having a `orient` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		'beep',
		'boop',
		'BOTTOM',
		5,
		NaN,
		null,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var title = new Title();
			title.orient = value;
		};
	}
});

tape( 'the constructor returns an instance having a `orient` property', function test( t ) {
	var title;

	title = new Title();
	t.strictEqual( title.orient, 'top', 'returns expected value' );

	title = new Title({
		'orient': 'bottom'
	});
	t.strictEqual( title.orient, 'bottom', 'returns expected value' );

	title = new Title({
		'orient': 'left'
	});
	t.strictEqual( title.orient, 'left', 'returns expected value' );

	title = new Title({
		'orient': 'right'
	});
	t.strictEqual( title.orient, 'right', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `orient` property which can be set to a valid method', function test( t ) {
	var title;

	title = new Title();

	title.orient = 'bottom';
	t.strictEqual( title.orient, 'bottom', 'returns expected value' );

	title.orient = 'top';
	t.strictEqual( title.orient, 'top', 'returns expected value' );

	title.orient = 'left';
	t.strictEqual( title.orient, 'left', 'returns expected value' );

	title.orient = 'right';
	t.strictEqual( title.orient, 'right', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `orient` property is set to a new value', function test( t ) {
	var title;
	var count;

	title = new Title();
	count = 0;

	title.on( 'change', onChange );

	title.orient = 'bottom';
	t.strictEqual( count, 1, 'returns expected value' );

	title.orient = 'top';
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	title.orient = 'top';
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
